{
  "案例": "MACHOs 作为暗物质主要来源的边缘性",
  "教学目标": "用通俗方式说明：MACHOs 是已知类型致密天体，但通常不能解释暗物质主体。",
  "分步拆解": [
    {
      "步骤": 1,
      "标题": "先分清概念",
      "讲解": "MACHOs 可理解为银河晕中不发光或弱发光的致密天体，例如褐矮星、低质量恒星、行星或黑洞。问题不是它们是否存在，而是它们能否占暗物质的大部分。",
      "观测证据": "微引力透镜可以探测不发光致密天体；已有事件说明银河系中存在致密天体。",
      "理论局限": "存在不等于数量足够；必须统计它们占银河晕质量的比例。"
    },
    {
      "步骤": 2,
      "标题": "用微引力透镜数数量",
      "讲解": "如果 MACHOs 很多，前景致密天体经过背景恒星时会短暂放大星光。通过统计这类事件率，可以反推 MACHOs 的丰度。",
      "观测证据": "多个微引力透镜巡天对银河晕中常见质量区间的 MACHOs 给出上限，通常只能解释暗物质的一小部分。",
      "理论局限": "上限依赖质量区间、视线方向与恒星分布模型，不能覆盖所有可能质量，尤其超大质量黑洞或极小质量黑洞。"
    },
    {
      "步骤": 3,
      "标题": "重子预算不够",
      "讲解": "多数 MACHOs 由普通重子物质构成。宇宙早期核合成和宇宙微波背景辐射能精确测量重子总量。",
      "观测证据": "轻元素丰度与宇宙微波背景辐射声学峰一致表明，重子物质约占宇宙总能量密度的百分之五，而暗物质约占百分之二十六。",
      "理论局限": "若 MACHOs 是主要暗物质且为重子，会超过重子上限；只有非重子致密天体，如某些黑洞，可绕开这一条，但会引入其他约束。"
    },
    {
      "步骤": 4,
      "标题": "致密天体自身也有约束",
      "讲解": "不同 MACHOs 有不同观测指纹：褐矮星会冷却发光，低质量恒星有光谱，黑洞可能有吸积或引力波信号。",
      "观测证据": "红外、亚毫米、射电、X 射线和引力波观测限制冷致密天体与原初黑洞的丰度；恒星形成模型也限制早期致密天体数量。",
      "理论局限": "黑洞 MACHOs 电磁信号弱，约束较难；仍需满足微透镜、吸积、星系中心恒星分布和结构形成等限制。"
    },
    {
      "步骤": 5,
      "标题": "与主流暗物质模型比较",
      "讲解": "暗物质主要来源需要同时解释宇宙大尺度结构和局部星系晕。非重子冷暗物质模型在早期宇宙中行为更合适。",
      "观测证据": "宇宙微波背景辐射、大尺度结构、星系团动力学和星系旋转曲线共同支持存在大量冷、非重子暗物质。",
      "理论局限": "粒子身份尚未直接确认，小尺度上仍有核球尖峰、缺失卫星等开放问题；但这些不意味着 MACHOs 更合适。"
    }
  ],
  "假设对比": {
    "MACHOs 假设": {
      "观测证据": "微引力透镜事件、致密天体存在、部分黑洞候选提供间接支持。",
      "理论局限": "常见 MACHOs 受重子密度上限、微透镜丰度上限、电磁与引力波约束限制，难以成为暗物质主体。"
    },
    "非重子冷暗物质假设": {
      "观测证据": "宇宙微波背景辐射、大尺度结构、星系团动力学和星系旋转曲线共同支持大量冷、非重子暗物质。",
      "理论局限": "粒子身份尚未直接确认，小尺度上仍有核球尖峰、缺失卫星等开放问题。"
    }
  },
  "结论": "MACHOs 可能贡献局部暗物质的一小部分，尤其某些黑洞，但通常不被认为是主要来源；因为重子预算和微透镜统计已把常见 MACHOs 的占比压得很低，而非重子冷暗物质能更好拟合宇宙学观测。"
}

{
  "案例": "超大质量原初黑洞作为边缘暗物质候选",
  "教学目标": "说明为什么质量特别大的原初黑洞通常难以成为主要暗物质，但在很窄的参数空间内仍可作为低丰度候选。",
  "分步拆解": [
    {
      "步骤": 1,
      "标题": "先定义原初黑洞",
      "讲解": "原初黑洞不是恒星死亡形成的黑洞，而是早期宇宙高密度扰动直接坍缩形成的致密天体。它们的质量可以很大，也可以很小。",
      "观测证据": "目前尚未直接探测到原初黑洞；相关证据主要来自对微引力透镜、宇宙微波背景辐射、引力波和大尺度结构的约束。",
      "理论局限": "原初黑洞的形成需要早期宇宙存在足够强的密度扰动，这类扰动本身会受到宇宙学观测限制。"
    },
    {
      "步骤": 2,
      "标题": "为什么大质量原初黑洞通常被排除",
      "讲解": "如果超大质量原初黑洞占暗物质的大部分，它们会留下多种可观测痕迹，例如吸积气体、微引力透镜事件、引力波信号，并影响早期宇宙结构形成。",
      "观测证据": "微引力透镜巡天、宇宙微波背景辐射各向异性、大尺度结构观测和引力波观测都对原初黑洞丰度给出上限。",
      "理论局限": "若原初黑洞形成时扰动过强，可能破坏宇宙微波背景辐射的均匀性或改变大尺度结构，因此高丰度模型通常被排除。"
    },
    {
      "步骤": 3,
      "标题": "为什么极小概率下仍算特殊候选",
      "讲解": "如果原初黑洞只占暗物质的一小部分，并且质量落在约束较弱的窗口，例如某些超大质量区间，那么单个质量大、数量少，微引力透镜和吸积信号都会变弱。",
      "观测证据": "现有观测通常给出的是上限，而不是绝对排除；在低丰度、窄质量窗口下，某些模型仍可能满足现有约束。",
      "理论局限": "这种候选依赖很特殊的早期宇宙物理，例如相变、标量场或特殊扰动谱，且不能解释全部暗物质。"
    },
    {
      "步骤": 4,
      "标题": "它为什么仍属于非重子暗物质候选",
      "讲解": "原初黑洞由引力坍缩形成，不消耗普通重子物质预算，因此可以绕开重子密度上限，成为非重子暗物质的可能成分。",
      "观测证据": "宇宙早期核合成和宇宙微波背景辐射表明重子物质总量有限，而暗物质总量明显更高。",
      "理论局限": "非重子身份只说明它不受重子上限限制，并不自动证明原初黑洞存在或丰度足够。"
    },
    {
      "步骤": 5,
      "标题": "与主流暗物质模型比较",
      "讲解": "主流模型通常假设暗物质是冷、非重子粒子或场，能较好解释宇宙大尺度结构。超大质量原初黑洞只是边缘补充，不是首选解释。",
      "观测证据": "宇宙微波背景辐射、大尺度结构、星系团动力学和星系旋转曲线共同支持大量冷暗物质存在。",
      "理论局限": "粒子暗物质身份尚未直接确认；原初黑洞模型则面临形成机制、丰度上限和小尺度结构约束。"
    }
  ],
  "假设对比": {
    "超大质量原初黑洞假设": {
      "观测证据": "微引力透镜、宇宙微波背景辐射、引力波和大尺度结构观测给出丰度上限；低丰度窄质量窗口尚未被完全排除。",
      "理论局限": "形成需要特殊早期宇宙扰动；高丰度模型通常被排除；只能作为暗物质的边缘补充。"
    },
    "非重子冷暗物质假设": {
      "观测证据": "宇宙微波背景辐射、大尺度结构、星系团动力学和星系旋转曲线共同支持大量冷、非重子暗物质。",
      "理论局限": "粒子身份尚未直接确认，小尺度结构问题仍未完全解决。"
    }
  },
  "结论": "超大质量原初黑洞通常不能作为暗物质主要来源，因为高丰度模型会受到微引力透镜、吸积、宇宙微波背景辐射和大尺度结构约束；但在低丰度、窄质量窗口和特殊形成机制下，它们仍可作为一种边缘性的非重子暗物质候选。"
}

{
  "案例": "自相互作用截面极低到几乎为零的粒子暗物质作为小尺度结构约束边界",
  "教学目标": "说明为什么“自相互作用截面几乎为零”在常规粒子暗物质模型中是标准近似，但在小尺度结构问题中会被当作一种极端约束情形来检验。",
  "分步拆解": [
    {
      "步骤": 1,
      "标题": "先解释自相互作用截面",
      "讲解": "自相互作用截面描述暗物质粒子之间发生散射或交换动量的概率。截面越低，暗物质越接近“只受引力影响”的冷暗物质；截面接近零时，暗物质粒子几乎不互相碰撞。",
      "观测证据": "宇宙大尺度结构、宇宙微波背景辐射和星系团动力学都支持存在大量冷、弱相互作用暗物质。",
      "理论局限": "“弱相互作用”不等于“完全无相互作用”；截面接近零只是模型中的一个极限情形，不是唯一可能。"
    },
    {
      "步骤": 2,
      "标题": "为什么极低截面通常不是异常",
      "讲解": "在标准冷暗物质模型中，暗物质自相互作用截面本来就极低，甚至近似为零。这个假设能很好解释宇宙大尺度结构，因此不是伪科学或异常假设。",
      "观测证据": "宇宙微波背景辐射声学峰、重子声学振荡、大尺度星系分布和星系团质量分布都与冷暗物质近似一致。",
      "理论局限": "大尺度成功不能自动解决小尺度问题，例如矮星系子结构数量、核球尖峰和星系团核心形态。"
    },
    {
      "步骤": 3,
      "标题": "为什么它会被当作边缘约束情形",
      "讲解": "当截面低到几乎为零时，暗物质在数值模拟中会形成大量小尺度子结构，并容易在星系中心形成较尖的密度峰。因此，这个极限值常被用来检验：如果观测显示小尺度结构比模拟少，零截面模型是否仍然成立。",
      "观测证据": "银河系周围矮卫星星系数量、矮椭圆星系中心密度分布、星系团核心形态等，都可能对过多子结构或过尖核球提出限制。",
      "理论局限": "观测到的子结构数量受恒星形成、反馈、潮汐剥离和观测选择效应影响，不能直接等同于暗物质子结构数量。"
    },
    {
      "步骤": 4,
      "标题": "小尺度观测如何给出约束",
      "讲解": "如果某些矮星系或星系团中心比零截面冷暗物质模拟更平滑，可能暗示暗物质存在某种非零自相互作用，用来抹平中心密度或减少子结构。反过来，如果观测只要求“不能太多相互作用”，则零截面仍可能允许。",
      "观测证据": "子弹星系团等星系团碰撞观测通常给出暗物质自相互作用截面上限，常见量级约为每克小于 1 平方厘米；某些矮星系和星系团核心分析可能给出更严格的上限。",
      "理论局限": "这些约束依赖模型假设，例如暗物质分布、碰撞几何、气体动力学和恒星反馈；不同观测给出的上限并不完全一致。"
    },
    {
      "步骤": 5,
      "标题": "为什么它仍是特殊约束情形",
      "讲解": "极低截面不是被普遍排除，而是作为参数空间的下边界：它代表“暗物质几乎不互相作用”的极限。小尺度结构观测可以检验这个极限是否过于成功，即是否预测了过多子结构或过尖核球。",
      "观测证据": "大尺度观测支持低截面冷暗物质；小尺度观测则提供额外压力，要求模型不能产生与观测明显不符的子结构。",
      "理论局限": "目前尚不能仅凭小尺度观测确定暗物质自相互作用截面必须非零；暖暗物质、反馈、恒星形成和观测不确定性都可能缓解零截面模型的张力。"
    }
  ],
  "假设对比": {
    "极低自相互作用截面冷暗物质": {
      "观测证据": "宇宙微波背景辐射、大尺度结构、星系团动力学支持低截面冷暗物质；星系团碰撞观测给出自相互作用上限。",
      "理论局限": "零截面极限可能预测过多小尺度子结构和较尖核球，与部分矮星系或星系团核心观测存在张力。"
    },
    "非零自相互作用暗物质": {
      "观测证据": "某些小尺度结构观测可能偏好暗物质具有有限自相互作用，以平滑中心密度或减少子结构。",
      "理论局限": "截面不能太大，否则会被星系团碰撞、矮星系速度色散和结构形成观测排除；具体数值依赖模型。"
    }
  },
  "结论": "自相互作用截面极低到几乎为零在常规粒子暗物质模型中是标准近似，不是异常；但在小尺度结构问题中，它被当作一种极端约束情形，因为零截面模型可能产生过多子结构或过尖核球。观测既支持低截面冷暗物质，也通过星系团和矮星系数据检验这个极限是否仍然成立。"
}

